423	    /**
424	     Consumes an attribute key off the queue, up to (but not including) whitespace or a comparison operator. CSS
425	     escapes in the key are decoded.
426	     */
427	    private String consumeAttributeKey(TokenQueue cq) {
428	        StringBuilder sb = StringUtil.borrowBuilder();
429	        OUT: while (!cq.isEmpty()) {
430	            if (cq.matchesWhitespace()) break;
431	            for (String eval : AttributeEvals) {
432	                if (cq.matches(eval)) break OUT;
433	            }
434	            if (cq.matches('\\')) cq.consumeCssEscapeSequence(sb);
435	            else sb.append(cq.consume());
436	        }
437	        return StringUtil.releaseBuilder(sb);
438	    }
439	
440	    /**
441	     Consumes an attribute value off the queue: either a quoted string (returned with its quotes, for decoding in the
442	     evaluator), or a bare value running to the next whitespace or the end of the queue.
443	     */
444	    private String consumeAttributeValue(TokenQueue cq) {
445	        if (cq.isEmpty()) return "";
446	
447	        if (cq.matches('"') || cq.matches('\'')) {
448	            StringBuilder sb = StringUtil.borrowBuilder();
449	            char quote = cq.consume();
450	            sb.append(quote);
451	            boolean closed = false;
452	            while (!cq.isEmpty()) {
453	                char c = cq.consume();
454	                sb.append(c);
455	                if (c == '\\' && !cq.isEmpty()) {
456	                    sb.append(cq.consume()); // keep the escaped character with its escape, for balanced decoding
457	                } else if (c == quote) {
458	                    closed = true;
459	                    break;
460	                }
461	            }
462	            if (!closed) {
463	                StringUtil.releaseBuilderVoid(sb);
464	                throw new Selector.SelectorParseException("Quoted value must have content");
465	            }
466	            return StringUtil.releaseBuilder(sb);
467	        }
468	
469	        // bare value, up to the next whitespace or the end of the queue
470	        StringBuilder sb = StringUtil.borrowBuilder();
471	        while (!cq.isEmpty() && !cq.matchesWhitespace()) sb.append(cq.consume());
472	        return StringUtil.releaseBuilder(sb);
473	    }
