475	    //pseudo selectors :first-child, :last-child, :nth-child, ...
476	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
477	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
478	
479	    private Evaluator cssNthChild(boolean last, boolean ofType) {
480	        String raw = consumeParens(); // arg is like "odd", or "-n+2", within nth-child(odd), optionally followed by " of S"
481	        final int ofIdx = indexOfOfClause(raw);
482	        final String arg = normalize(ofIdx >= 0 ? raw.substring(0, ofIdx) : raw);
483	        final boolean hasOf = ofIdx >= 0;
484	
485	        if (hasOf && ofType)
486	            throw new Selector.SelectorParseException(
487	                "Could not parse query '%s': 'of S' is only supported by :nth-child and :nth-last-child", query);
488	
489	        final int step, offset;
490	        if ("odd".equals(arg)) {
491	            step = 2;
492	            offset = 1;
493	        } else if ("even".equals(arg)) {
494	            step = 2;
495	            offset = 0;
496	        } else {
497	            Matcher stepOffsetM, stepM;
498	            if ((stepOffsetM = NthStepOffset.matcher(arg)).matches()) {
499	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
500	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
501	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
502	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
503	                offset =
504	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
505	            } else if ((stepM = NthOffset.matcher(arg)).matches()) {
506	                step = 0;
507	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
508	            } else {
509	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", arg);
510	            }
511	        }
512	
513	        if (hasOf) {
514	            String subQuery = raw.substring(ofIdx + 2).trim(); // skip the "of" keyword
515	            Validate.notEmpty(subQuery, ":nth-child(An+B of S) selector S must not be empty");
516	            Evaluator selector = parse(subQuery); // a comma-separated complex selector list; validates the full grammar
517	            return new Evaluator.IsNthChildOf(step, offset, last, selector);
518	        }
519	
520	        return ofType
521	            ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
522	            : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
523	    }
524	
525	    /**
526	     Finds the index of the {@code of} keyword separating An+B from the selector list in an
527	     {@code :nth-child(An+B of S)} argument. The keyword must be bounded on both sides by whitespace, and is not
528	     matched inside quoted strings (so attribute values containing " of " are preserved).
529	     @return the index of the 'o' in 'of', or -1 if there is no of clause
530	     */
531	    private static int indexOfOfClause(String arg) {
532	        boolean inSingle = false;
533	        boolean inDouble = false;
534	        boolean prevEscaped = false;
535	        for (int i = 0; i < arg.length(); i++) {
536	            char c = arg.charAt(i);
537	            if (c == '\\' && i + 1 < arg.length()) {
538	                i++; // skip the escaped char
539	                prevEscaped = true;
540	                continue;
541	            }
542	            if (!inDouble && c == '\'')
543	                inSingle = !inSingle;
544	            else if (!inSingle && c == '"')
545	                inDouble = !inDouble;
546	
547	            if (!inSingle && !inDouble && !prevEscaped
548	                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
549	                && arg.regionMatches(true, i, "of", 0, 2)
550	                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
551	                return i;
552	            }
553	            prevEscaped = false;
554	        }
555	        return -1;
556	    }
557	
558	    private String consumeParens() {
559	        return tq.chompBalanced('(', ')');
560	    }
561	
562	    private int consumeIndex() {
563	        String index = consumeParens().trim();
564	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
565	        return Integer.parseInt(index);
566	    }
567	
568	    // pseudo selector :has(el)
569	    private Evaluator has() {
570	        return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
571	    }
572	
573	    // pseudo selector :is()
574	    private Evaluator is() {
575	        return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
576	    }
577	
578	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
579	        Validate.isTrue(tq.matchChomp('('), err);
580	        Evaluator eval = parseSelectorGroup();
581	        Validate.isTrue(tq.matchChomp(')'), err);
582	        return func.apply(eval);
583	    }
584	
585	    // pseudo selector :contains(text), containsOwn(text)
586	    private Evaluator contains(boolean own) {
587	        String query = own ? ":containsOwn" : ":contains";
588	        String searchText = TokenQueue.unescape(consumeParens());
589	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
590	
591	        if (inNodeContext)
592	            return new NodeEvaluator.ContainsValue(searchText);
593	
594	        return own
595	            ? new Evaluator.ContainsOwnText(searchText)
596	            : new Evaluator.ContainsText(searchText);
597	    }
598	
599	    private Evaluator containsWholeText(boolean own) {
600	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
601	        String searchText = TokenQueue.unescape(consumeParens());
602	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
603	        return own
604	            ? new Evaluator.ContainsWholeOwnText(searchText)
605	            : new Evaluator.ContainsWholeText(searchText);
606	    }
607	
608	    // pseudo selector :containsData(data)
609	    private Evaluator containsData() {
610	        String searchText = TokenQueue.unescape(consumeParens());
611	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
612	        return new Evaluator.ContainsData(searchText);
613	    }
614	
615	    // :matches(regex), matchesOwn(regex)
616	    private Evaluator matches(boolean own) {
617	        String query = own ? ":matchesOwn" : ":matches";
618	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
619	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
620	        Regex pattern = Regex.compile(regex);
621	
622	        if (inNodeContext)
623	            return new NodeEvaluator.MatchesValue(pattern);
624	
625	        return own
626	            ? new Evaluator.MatchesOwn(pattern)
627	            : new Evaluator.Matches(pattern);
628	    }
629	
630	    // :matches(regex), matchesOwn(regex)
631	    private Evaluator matchesWholeText(boolean own) {
632	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
633	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
634	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
635	
636	        Regex pattern = Regex.compile(regex);
637	        return own
638	            ? new Evaluator.MatchesWholeOwnText(pattern)
639	            : new Evaluator.MatchesWholeText(pattern);
640	    }
641	
642	    // :not(selector)
643	    private Evaluator not() {
644	        String subQuery = consumeParens();
645	        Validate.notEmpty(subQuery, ":not(selector) subselect must not be empty");
646	
647	        return new StructuralEvaluator.Not(parse(subQuery));
648	    }
649	
650	    @Override
651	    public String toString() {
652	        return query;
653	    }
654	
655	    @Override
656	    public void close() {
657	        tq.close();
658	    }
659	}
