import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class Verify {
    static Document doc;
    static int failures = 0;

    public static void main(String[] args) {
        String html = "<div id=1 data-v='A B'></div>"
            + "<div id=2 data-v='a b'></div>"
            + "<div id=3 data-v='x\"y'></div>"
            + "<div id=4 data-v=''></div>"
            + "<div id=5 data-v=Alpha></div>"
            + "<div id=6></div>";
        doc = Jsoup.parse(html);
        String before = doc.html();

        // quoted exact with escaped space hits only #1
        check("[data-v=\"A\\ B\"]", "1");
        check("[data-v=\"A B\"]", "1");
        // s flag: only exact case
        check("[data-v=\"A B\" s]", "1");
        check("[data-v=\"a b\" s]", "2");
        // i flag
        check("[data-v=\"A B\" i]", "1,2");
        // bare value case-insensitive
        check("[data-v=alpha]", "5");
        check("[data-v^=al]", "5");
        // case-sensitive prefix must not hit
        check("[data-v^=al s]", "");
        check("[data-v^=Al s]", "5");
        // negation includes missing and empty, excludes exact equals
        check("[data-v!=\"A B\" s]", "2,3,4,5,6");
        check("[data-v!=\"A B\" i]", "3,4,5,6");
        // hex-escaped attribute name same results (\64 = 'd')
        check("[\\64 ata-v=\"A B\"]", "1");
        check("[\\64 ata-v^=al]", "5");
        // quoted value containing quote char
        check("[data-v='x\"y']", "3");
        // empty value
        check("[data-v=\"\"]", "4");
        // existence
        check("[data-v]", "1,2,3,4,5");

        // errors
        expectFail("[data-v");           // unclosed bracket
        expectFail("[data-v=\"A B]");    // unclosed quote
        expectFail("[data-v=\"A B\\");   // hmm - escape swallows... unclosed quote actually
        expectFail("[data-v=]");         // operator missing value
        expectFail("[data-v=A B q]");    // unknown modifier
        expectFail("[data-v=A B i i]");  // duplicate modifier
        expectFail("[data-v i=A]");      // misplaced modifier
        expectFail("[data-v=A B]extra"); // trailing junk? actually 'extra' would be... 
        expectFail("div,");              // incomplete list
        expectFail("[data-v=A\\");       // escape at end (unclosed bracket too)

        // doc unchanged
        if (!doc.html().equals(before)) { System.out.println("FAIL: document mutated"); failures++; }

        System.out.println(failures == 0 ? "ALL OK" : failures + " FAILURES");
    }

    static void check(String q, String expectIds) {
        try {
            Elements els = doc.select(q);
            StringBuilder sb = new StringBuilder();
            for (var e : els) { if (sb.length() > 0) sb.append(','); sb.append(e.id()); }
            if (!sb.toString().equals(expectIds)) {
                System.out.println("FAIL " + q + " -> [" + sb + "] expected [" + expectIds + "]");
                failures++;
            }
        } catch (Exception e) {
            System.out.println("FAIL " + q + " threw " + e);
            failures++;
        }
    }

    static void expectFail(String q) {
        try {
            Elements els = doc.select(q);
            System.out.println("FAIL (no throw) " + q + " -> " + els.size() + " results");
            failures++;
        } catch (Selector.SelectorParseException e) {
            // ok
        } catch (Exception e) {
            System.out.println("FAIL (wrong ex) " + q + " -> " + e);
            failures++;
        }
    }
}
