import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;

public class Verify2 {
    public static void main(String[] args) {
        Document doc = Jsoup.parse("<a id=a data-v=\"A B\"></a><a id=b data-v=\"a b\"></a><i id=e></i>");
        // hex escape immediately followed by hex-letter char: \64 + "ata-v"
        // \64a would be a different codepoint if greedy; CSS says consume up to 6 hex digits -> \064a...
        System.out.println("[\\64 ata-v] -> " + ids(doc.select("[\\64 ata-v]")));
        System.out.println("[\\64ata-v] -> " + ids(doc.select("[\\64ata-v]")));
        System.out.println("[\\64  ata-v] -> " + ids(doc.select("[\\64  ata-v]"))); // hex + terminator space + ws
        // escape before operator must not swallow '='
        System.out.println("[data\\-v=A B] -> " + ids(doc.select("[data\\-v=A B]")));
        System.out.println("[data\\=v] -> " + ids(doc.select("[data\\=v]"))); // escaped '=' in key
        // escaped closing bracket in quoted value
        System.out.println("[data-v=\"A\\] B\"] -> " + ids(doc.select("[data-v=\"A\\] B\"]")));
        // hex escape in value
        System.out.println("[data-v=\"\\41  B\"] -> " + ids(doc.select("[data-v=\"\\41  B\"]"))); // \41 = 'A'
        System.out.println("[data-v=\"\\41 B\"] -> " + ids(doc.select("[data-v=\"\\41 B\"]")));
    }
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        els.forEach(e -> sb.append(e.id()).append(' '));
        return sb.toString();
    }
}
